create or replace package body onboarding_api as
  procedure add_hire(p_person_id in number, p_name in varchar2,
                     p_email in varchar2, p_phone in varchar2) is
  begin
    -- Ensure the person exists in HR_PEOPLE first, as HR_CONTACTS references it.
    -- We use MERGE or INSERT/UPDATE logic. Since we don't know if the person exists,
    -- we insert into HR_PEOPLE if they don't exist, assuming p_name is the full name.
    insert into hr_people (person_id, full_name)
    select p_person_id, p_name
    where not exists (select 1 from hr_people where person_id = p_person_id);

    -- Now insert into HR_CONTACTS, which is the correct target for contact details.
    insert into hr_contacts (person_id, email, phone)
    values (p_person_id, p_email, p_phone);
  end add_hire;

  function email_of(p_person_id in number) return varchar2 is
    l_email employee_directory_v.email%type;
  begin
    select email into l_email from employee_directory_v where person_id = p_person_id;
    return l_email;
  end email_of;

  function phone_of(p_person_id in number) return varchar2 is
    l_phone employee_directory_v.phone%type;
  begin
    select phone into l_phone from employee_directory_v where person_id = p_person_id;
    return l_phone;
  end phone_of;
end onboarding_api;
